'use client';

import {
  ScrollArea as ScrollAreaPrimitive,
  useScrollArea,
  useScrollAreaContext,
} from '@ark-ui/react/scroll-area';
import { clsx } from 'clsx';
import type { ComponentProps, ComponentRef } from 'react';
import { forwardRef } from 'react';
import styles from './ScrollArea.module.css';

type ScrollAreaVariant = 'hover' | 'always';
type ScrollAreaRootProps = ComponentProps<typeof ScrollAreaPrimitive.Root> & {
  fade?: boolean;
  variant?: ScrollAreaVariant;
};
type ScrollAreaRootProviderProps = ComponentProps<typeof ScrollAreaPrimitive.RootProvider> & {
  fade?: boolean;
  variant?: ScrollAreaVariant;
};

const ScrollArea = forwardRef<ComponentRef<typeof ScrollAreaPrimitive.Root>, ScrollAreaRootProps>(
  function ScrollArea({ className, fade, variant = 'hover', ...props }, ref) {
    return (
      <ScrollAreaPrimitive.Root
        ref={ref}
        {...props}
        data-slot="scroll-area-root"
        data-fade={fade ? '' : undefined}
        data-variant={variant}
        className={clsx(styles.root, className)}
      />
    );
  },
);

const ScrollAreaRootProvider = forwardRef<
  ComponentRef<typeof ScrollAreaPrimitive.RootProvider>,
  ScrollAreaRootProviderProps
>(function ScrollAreaRootProvider({ className, fade, variant = 'hover', ...props }, ref) {
  return (
    <ScrollAreaPrimitive.RootProvider
      ref={ref}
      {...props}
      data-slot="scroll-area-root-provider"
      data-fade={fade ? '' : undefined}
      data-variant={variant}
      className={clsx(styles.root, className)}
    />
  );
});

const ScrollAreaViewport = forwardRef<
  ComponentRef<typeof ScrollAreaPrimitive.Viewport>,
  ComponentProps<typeof ScrollAreaPrimitive.Viewport>
>(function ScrollAreaViewport({ className, ...props }, ref) {
  return (
    <ScrollAreaPrimitive.Viewport
      ref={ref}
      {...props}
      data-slot="scroll-area-viewport"
      className={clsx(styles.viewport, className)}
    />
  );
});

const ScrollAreaContent = forwardRef<
  ComponentRef<typeof ScrollAreaPrimitive.Content>,
  ComponentProps<typeof ScrollAreaPrimitive.Content>
>(function ScrollAreaContent(props, ref) {
  return <ScrollAreaPrimitive.Content ref={ref} {...props} data-slot="scroll-area-content" />;
});

const ScrollAreaScrollbar = forwardRef<
  ComponentRef<typeof ScrollAreaPrimitive.Scrollbar>,
  ComponentProps<typeof ScrollAreaPrimitive.Scrollbar>
>(function ScrollAreaScrollbar({ className, ...props }, ref) {
  return (
    <ScrollAreaPrimitive.Scrollbar
      ref={ref}
      {...props}
      data-slot="scroll-area-scrollbar"
      className={clsx(styles.scrollbar, className)}
    />
  );
});

const ScrollAreaThumb = forwardRef<
  ComponentRef<typeof ScrollAreaPrimitive.Thumb>,
  ComponentProps<typeof ScrollAreaPrimitive.Thumb>
>(function ScrollAreaThumb({ className, ...props }, ref) {
  return (
    <ScrollAreaPrimitive.Thumb
      ref={ref}
      {...props}
      data-slot="scroll-area-thumb"
      className={clsx(styles.thumb, className)}
    />
  );
});

const ScrollAreaCorner = forwardRef<
  ComponentRef<typeof ScrollAreaPrimitive.Corner>,
  ComponentProps<typeof ScrollAreaPrimitive.Corner>
>(function ScrollAreaCorner(props, ref) {
  return <ScrollAreaPrimitive.Corner ref={ref} {...props} data-slot="scroll-area-corner" />;
});

const ScrollAreaContext = ScrollAreaPrimitive.Context;

export {
  ScrollArea,
  ScrollAreaContext,
  ScrollAreaContent,
  ScrollAreaCorner,
  ScrollAreaRootProvider,
  ScrollAreaScrollbar,
  ScrollAreaThumb,
  ScrollAreaViewport,
  useScrollArea,
  useScrollAreaContext,
};
export type { ScrollAreaRootProps, ScrollAreaRootProviderProps, ScrollAreaVariant };

@layer moduix.components {
  .root {
    box-sizing: border-box;
    width: 100%;
    height: 100%;
    min-width: 0;
    min-height: 0;
  }

  .viewport {
    --_scroll-area-fade-size: var(--moduix-scroll-area-fade-size, var(--moduix-spacing-10));

    box-sizing: border-box;
    width: 100%;
    height: 100%;
    min-width: 0;
    min-height: 0;
    border-radius: inherit;
    outline: 0;
    scrollbar-width: none;

    &::-webkit-scrollbar {
      display: none;
    }

    .root[data-fade] & {
      mask-image: linear-gradient(
        to bottom,
        transparent,
        black min(var(--_scroll-area-fade-size), var(--scroll-area-overflow-y-start, 0px)),
        black
          calc(100% - min(var(--_scroll-area-fade-size), var(--scroll-area-overflow-y-end, 0px))),
        transparent
      );
      mask-repeat: no-repeat;
    }

    &:focus-visible {
      outline: var(--moduix-focus-ring-inset-width) solid var(--moduix-color-ring);
      outline-offset: var(--moduix-focus-ring-inset-offset);
    }
  }

  /* Ark positions the scrollbar inline; this rule only sizes, hides, and reveals it. */
  .scrollbar {
    --_scroll-area-scrollbar-size: var(
      --moduix-scroll-area-scrollbar-size,
      var(--moduix-spacing-1)
    );

    margin: var(--moduix-spacing-1);
    opacity: 0;
    pointer-events: none;
    transition:
      opacity var(--moduix-transition-default),
      width var(--moduix-transition-fast),
      height var(--moduix-transition-fast);

    /* Wider invisible hit area for grabbing the thin track. */
    &::before {
      content: '';
      position: absolute;
    }

    &[data-orientation='vertical'] {
      width: var(--_scroll-area-scrollbar-size);
      margin-inline-start: 0;

      &::before {
        inset-block: 0;
        inset-inline: calc(var(--moduix-spacing-2) * -1);
      }

      &:not([data-overflow-y]) {
        display: none;
      }

      &[data-dragging] {
        width: calc(var(--_scroll-area-scrollbar-size) + 2px);
      }

      @media (hover: hover) {
        &:hover {
          width: calc(var(--_scroll-area-scrollbar-size) + 2px);
        }
      }
    }

    &[data-orientation='horizontal'] {
      height: var(--_scroll-area-scrollbar-size);
      margin-block-start: 0;

      &::before {
        inset-inline: 0;
        inset-block: calc(var(--moduix-spacing-2) * -1);
      }

      &:not([data-overflow-x]) {
        display: none;
      }

      &[data-dragging] {
        height: calc(var(--_scroll-area-scrollbar-size) + 2px);
      }

      @media (hover: hover) {
        &:hover {
          height: calc(var(--_scroll-area-scrollbar-size) + 2px);
        }
      }
    }

    &[data-hover],
    &[data-scrolling],
    .root[data-variant='always'] & {
      opacity: 1;
      pointer-events: auto;
    }

    &[data-scrolling] {
      transition-duration: 0ms;
    }
  }

  .thumb {
    border-radius: var(--moduix-radius-full);
    background-color: var(--moduix-scroll-area-thumb-bg, var(--moduix-color-border));

    &[data-orientation='vertical'] {
      width: 100%;
      min-height: var(--moduix-size-xs);
    }

    &[data-orientation='horizontal'] {
      height: 100%;
      min-width: var(--moduix-size-xs);
    }
  }

  @media (forced-colors: active) {
    .root[data-fade] .viewport {
      mask-image: none;
    }

    .viewport:focus-visible {
      outline-color: Highlight;
    }

    .thumb {
      background-color: ButtonText;
    }
  }
}
